CREATE OR REPLACE FUNCTION CALCULATE_ORDER_TOTAL(P_PRODUCT_ID NUMBER, P_QUANTITY NUMBER)
RETURN NUMBER
IS
    V_PRICE NUMBER(10, 2);
BEGIN
    SELECT PRICE INTO V_PRICE FROM PRODUCTS WHERE ID = P_PRODUCT_ID;
    RETURN P_QUANTITY * V_PRICE;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 0;
END;

CREATE VIEW "PRODUCT_INVENTORY" AS SELECT 
    P.ID,
    P.NAME,
    P.PRICE,
    P.STOCK,
    NVL(SUM(O.QUANTITY), 0) AS TOTAL_ORDERED
FROM PRODUCTS P
LEFT JOIN ORDERS O ON P.ID = O.PRODUCT_ID
GROUP BY P.ID, P.NAME, P.PRICE, P.STOCK;
CREATE MATERIALIZED VIEW "PRODUCT_STATS" AS SELECT 
    PRODUCT_ID,
    COUNT(*) AS ORDER_COUNT,
    SUM(QUANTITY) AS TOTAL_QUANTITY,
    SUM(TOTAL) AS TOTAL_REVENUE
FROM ORDERS
GROUP BY PRODUCT_ID
;
COMMENT ON MATERIALIZED VIEW "PRODUCT_STATS" IS 'snapshot table for snapshot TESTSCHEMA.PRODUCT_STATS';
COMMENT ON MATERIALIZED VIEW "PRODUCT_STATS" IS 'snapshot table for snapshot TESTSCHEMA.PRODUCT_STATS';
